    USING (("employeeId" = CAST((SELECT auth.uid()) AS text) AND "companyId" = ANY(CAST((SELECT get_companies_with_employee_role() AS get_companies_with_employee_role) AS text[]))) OR "companyId" = ANY(CAST((SELECT get_companies_with_employee_permission(CAST('people_view' AS text)) AS get_companies_with_employee_permission) AS text[])));

